mapper.select:
SELECT ${selectColumns}
FROM ${tableName}
WHERE api_code = #{apiCode}
  AND DATE(create_time) = #{today}
ORDER BY create_time DESC, id DESC
LIMIT 1

SELECT ${selectColumns}
FROM ${tableName}
WHERE api_code = #{apiCode}
  AND create_time >= #{startTime}
  AND create_time <= #{endTime}
ORDER BY create_time DESC, id DESC
LIMIT 1
